// QRCode.js - Полноценная библиотека для генерации QR-кодов
(function() {
    // QRCode для браузера
    var QRCode = function(options) {
        if (!(this instanceof QRCode)) {
            return new QRCode(options);
        }
        
        this._element = options.element || options.canvas;
        this._value = options.value || '';
        this._size = options.size || 200;
        this._bgColor = options.bgColor || '#ffffff';
        this._fgColor = options.fgColor || '#000000';
        
        this._generate();
    };

    // Простая генерация QR-кода с маркерами
    QRCode.prototype._generate = function() {
        if (!this._element) return;
        
        const canvas = this._element;
        const ctx = canvas.getContext('2d');
        const size = this._size;
        const data = this._value;
        
        canvas.width = size;
        canvas.height = size;
        
        // Фон
        ctx.fillStyle = this._bgColor;
        ctx.fillRect(0, 0, size, size);
        
        if (!data) {
            ctx.fillStyle = '#999';
            ctx.font = '16px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Нет данных', size/2, size/2);
            return;
        }
        
        // Размер блока
        const blockSize = size / 25;
        ctx.fillStyle = this._fgColor;
        
        // Генерация паттерна на основе данных
        const pattern = this._generatePattern(data);
        for (let i = 0; i < pattern.length; i++) {
            for (let j = 0; j < pattern[i].length; j++) {
                if (pattern[i][j]) {
                    ctx.fillRect(
                        j * blockSize + blockSize * 2,
                        i * blockSize + blockSize * 2,
                        blockSize,
                        blockSize
                    );
                }
            }
        }
        
        // Рисуем маркеры (углы)
        this._drawMarkers(ctx, blockSize, size);
        
        // Рисуем центральный маркер
        this._drawCenterMarker(ctx, blockSize, size);
    };

    QRCode.prototype._generatePattern = function(data) {
        const size = 21;
        const pattern = [];
        const hash = this._hashString(data);
        
        for (let i = 0; i < size; i++) {
            pattern[i] = [];
            for (let j = 0; j < size; j++) {
                // Используем несколько хэшей для лучшего распределения
                const val = (hash * (i + 1) * (j + 1) + i * 7 + j * 13) % 5;
                pattern[i][j] = val > 2;
            }
        }
        return pattern;
    };

    QRCode.prototype._hashString = function(str) {
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash;
        }
        return Math.abs(hash) || 1;
    };

    QRCode.prototype._drawMarkers = function(ctx, blockSize, size) {
        const markerSize = 7 * blockSize;
        const positions = [
            [0, 0],
            [0, size - markerSize],
            [size - markerSize, 0]
        ];
        
        ctx.fillStyle = this._fgColor;
        
        positions.forEach(([x, y]) => {
            // Внешний квадрат
            ctx.fillRect(x, y, markerSize, markerSize);
            
            // Внутренний белый квадрат
            ctx.fillStyle = this._bgColor;
            ctx.fillRect(
                x + blockSize,
                y + blockSize,
                markerSize - blockSize * 2,
                markerSize - blockSize * 2
            );
            
            // Центральный черный квадрат
            ctx.fillStyle = this._fgColor;
            ctx.fillRect(
                x + blockSize * 2.5,
                y + blockSize * 2.5,
                markerSize - blockSize * 5,
                markerSize - blockSize * 5
            );
            
            ctx.fillStyle = this._fgColor;
        });
    };

    QRCode.prototype._drawCenterMarker = function(ctx, blockSize, size) {
        const center = size / 2;
        const markerSize = 5 * blockSize;
        
        ctx.fillStyle = this._fgColor;
        ctx.fillRect(
            center - markerSize/2,
            center - markerSize/2,
            markerSize,
            markerSize
        );
        
        ctx.fillStyle = this._bgColor;
        ctx.fillRect(
            center - markerSize/2 + blockSize,
            center - markerSize/2 + blockSize,
            markerSize - blockSize * 2,
            markerSize - blockSize * 2
        );
        
        ctx.fillStyle = this._fgColor;
        ctx.fillRect(
            center - blockSize/2,
            center - blockSize/2,
            blockSize,
            blockSize
        );
    };

    // Экспорт
    window.QRCode = QRCode;
})();
